export type ParsedReclaimInstruction<
  TProgram extends string = typeof MYBARPOOL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /**
     * A box owner of the pool; pays the rent of their own associated token account when this
     * call creates it.
     */
    boxOwner: TAccountMetas[0];
    /** PROGRAM §3.2 `GameRecord`, the pool's game (`has_one`); read for the scheduled kickoff. */
    game: TAccountMetas[1];
    /** PROGRAM §3.3 `Pool`, re-derived from its own fields; anything but `Settled`. */
    pool: TAccountMetas[2];
    /** PROGRAM §3.4 vault; the reclaim comes out of it. */
    vault: TAccountMetas[3];
    /**
     * PROGRAM §3.5 the creator's counter for this game; required and decremented exactly when
     * the pool is still `Open`, never read otherwise.
     */
    counter?: TAccountMetas[4] | undefined;
    /** The pool's mint (`address = pool.mint`); SPL pools only. */
    mint?: TAccountMetas[5] | undefined;
    /** pools only. */
    boxOwnerTokenAccount?: TAccountMetas[6] | undefined;
    /** The pool's token program (checked against `pool.token_program`); SPL pools only. */
    tokenProgram?: TAccountMetas[7] | undefined;
    /** The associated-token program, a fixed address; SPL pools only. */
    associatedTokenProgram?: TAccountMetas[8] | undefined;
    /** For the SOL transfer out of the vault and any ATA rent. */
    systemProgram: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: ReclaimInstructionData;
};

export function parseReclaimInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedReclaimInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 12,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === MYBARPOOL_PROGRAM_ADDRESS ? undefined : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      boxOwner: getNextAccount(),
      game: getNextAccount(),
      pool: getNextAccount(),
      vault: getNextAccount(),
      counter: getNextOptionalAccount(),
      mint: getNextOptionalAccount(),
      boxOwnerTokenAccount: getNextOptionalAccount(),
      tokenProgram: getNextOptionalAccount(),
      associatedTokenProgram: getNextOptionalAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getReclaimInstructionDataDecoder().decode(instruction.data),
  };
}
